-- cre8-admin — baseline schema (captured from production 2026-11-16)
--
-- Generated by scripts/capture-schema.js. Do not hand-edit: regenerate it, or
-- add a new dated migration alongside it for an incremental change.
--
-- WHY THIS FILE EXISTS
-- The tables below were created by hand in the Supabase dashboard or by
-- ad-hoc scripts, so the schema for the deal pipeline, the listings workflow,
-- market intel and the logo library existed ONLY in the live project.
-- supabase/migrations/ held six email migrations and nothing else, which
-- meant the database could not be rebuilt from the repo and there was no way
-- to stand up a staging copy.
--
-- This is a point-in-time capture of what production actually looks like,
-- read out of information_schema and pg_catalog. It is idempotent
-- (if not exists / or replace / exception-guarded DO blocks throughout), so
-- it is safe to run against the existing project, where it is a no-op.
--
-- SCOPE: the 16 tables cre8-admin reads. The same Supabase project also
-- hosts cre8-map's tables (sale_comps, census_tracts, zoning_sources,
-- site_plans, planning_events, …) and the PostGIS extension. Those are
-- deliberately NOT in this file — they belong to that repo.
--
-- Row Level Security is not configured on these tables and this file does not
-- add it. The admin reaches Supabase only through server-side API routes
-- using the service-role key, which bypasses RLS by design.

begin;

create extension if not exists "uuid-ossp";
create extension if not exists pg_trgm;


-- ============================================================
-- Enum types
-- ============================================================

do $$ begin
  create type deal_status as enum ('active', 'due_diligence', 'closing', 'closed', 'cancelled');
exception when duplicate_object then null; end $$;
do $$ begin
  create type deal_type as enum ('sale', 'lease');
exception when duplicate_object then null; end $$;
do $$ begin
  create type intel_category as enum ('data-center', 'retail', 'land', 'market', 'infrastructure');
exception when duplicate_object then null; end $$;
do $$ begin
  create type intel_status as enum ('pending', 'live', 'deleted', 'needs_text');
exception when duplicate_object then null; end $$;


-- ============================================================
-- Trigger functions (defined first — the triggers below use them)
-- ============================================================

create or replace function public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;

create or replace function public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;

create or replace function public.update_market_intel_timestamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$;


-- ============================================================
-- Brokers — referenced by deals, deal_members and campaigns
-- ============================================================

create table if not exists brokers (
  id uuid default gen_random_uuid() not null,
  name text not null,
  email text not null,
  phone text not null,
  title text default ''::text not null,
  headshot_url text,
  bio text,
  years_experience integer,
  transactions_count integer,
  sort_order integer default 0 not null,
  webflow_id text,
  created_at timestamptz default now() not null,
  updated_at timestamptz default now() not null,
  default_commission_rate numeric default 0.03,
  default_broker_split numeric default 0.50,
  default_additional_splits jsonb default '[]'::jsonb,
  constraint brokers_pkey PRIMARY KEY (id)
);

drop trigger if exists set_updated_at_brokers on brokers;
CREATE TRIGGER set_updated_at_brokers BEFORE UPDATE ON public.brokers FOR EACH ROW EXECUTE FUNCTION update_updated_at();


-- ============================================================
-- Deal pipeline (CRE8 Flow)
-- ============================================================

create table if not exists deals (
  id uuid default gen_random_uuid() not null,
  broker_id uuid not null,
  deal_name text not null,
  property_address text,
  deal_type deal_type default 'sale'::deal_type not null,
  price numeric(15,2),
  commission_rate numeric(5,4) default 0.03 not null,
  broker_split numeric(5,4) default 0.50 not null,
  effective_date date,
  escrow_open_date date,
  feasibility_days integer,
  dd_extension_date date,
  inside_close_days integer,
  outside_close_days integer,
  status deal_status default 'active'::deal_status not null,
  actual_close_date date,
  cancel_reason text,
  notes text,
  created_at timestamptz default now() not null,
  updated_at timestamptz default now() not null,
  listing_id text,
  parcel_number text,
  additional_splits jsonb default '[]'::jsonb,
  sharepoint_folder_url text,
  escrow_number text,
  escrow_company text,
  lease_stage text default 'negotiating_loi'::text not null,
  w9_status text default 'pending'::text not null,
  constraint deals_pkey PRIMARY KEY (id)
);

create index if not exists idx_deals_broker ON public.deals USING btree (broker_id);
create index if not exists idx_deals_status ON public.deals USING btree (status);
drop trigger if exists set_updated_at_deals on deals;
CREATE TRIGGER set_updated_at_deals BEFORE UPDATE ON public.deals FOR EACH ROW EXECUTE FUNCTION update_updated_at();

create table if not exists deal_members (
  id uuid default gen_random_uuid() not null,
  deal_id uuid not null,
  broker_id uuid not null,
  split_percent numeric,
  created_at timestamptz default now(),
  constraint deal_members_pkey PRIMARY KEY (id),
  constraint deal_members_deal_id_broker_id_key UNIQUE (deal_id, broker_id)
);

create index if not exists idx_deal_members_broker ON public.deal_members USING btree (broker_id);
create index if not exists idx_deal_members_deal ON public.deal_members USING btree (deal_id);

create table if not exists deal_dates (
  id uuid default gen_random_uuid() not null,
  deal_id uuid not null,
  label text not null,
  date date not null,
  offset_days integer,
  offset_from text,
  sort_order integer default 0 not null,
  created_at timestamptz default now(),
  constraint deal_dates_pkey PRIMARY KEY (id)
);

create index if not exists idx_deal_dates_deal ON public.deal_dates USING btree (deal_id);

create table if not exists lease_payments (
  id uuid default gen_random_uuid() not null,
  deal_id uuid not null,
  sort_order integer default 0 not null,
  percent numeric not null,
  payment_date date,
  offset_days integer,
  offset_from text,
  received boolean default false not null,
  received_date date,
  created_at timestamptz default now(),
  constraint lease_payments_pkey PRIMARY KEY (id)
);

create index if not exists idx_lease_payments_deal ON public.lease_payments USING btree (deal_id);


-- ============================================================
-- Listings workflow
-- ============================================================

create table if not exists listing_checklists (
  id uuid default gen_random_uuid() not null,
  listing_id text not null,
  listing_name text,
  is_new boolean default true not null,
  items jsonb default '{"crexi": false, "flyer": false, "costar": false, "la_sent": false, "loopnet": false, "published": false, "email_blast": false, "la_executed": false}'::jsonb not null,
  listing_agreement_url text,
  created_at timestamptz default now() not null,
  updated_at timestamptz default now() not null,
  constraint listing_checklists_pkey PRIMARY KEY (id),
  constraint listing_checklists_listing_id_key UNIQUE (listing_id)
);

create table if not exists listing_priorities (
  listing_id text not null,
  listing_name text,
  rank integer not null,
  updated_at timestamptz default now() not null,
  constraint listing_priorities_pkey PRIMARY KEY (listing_id)
);

create index if not exists listing_priorities_rank_idx ON public.listing_priorities USING btree (rank);


-- ============================================================
-- Email campaigns
-- ============================================================

create table if not exists email_campaigns (
  id uuid default gen_random_uuid() not null,
  listing_id text not null,
  listing_name text not null,
  campaign_type text not null,
  email_label text not null,
  heading_text text,
  body_text text,
  photo_url text,
  highlights jsonb default '[]'::jsonb,
  listing_page_url text,
  broker_id text not null,
  broker_name text not null,
  broker_email text not null,
  broker_phone text,
  segment_id text,
  segment_name text default 'All Contacts'::text not null,
  frequency text,
  scheduled_date timestamptz,
  next_send_date timestamptz,
  end_date timestamptz,
  status text default 'draft'::text not null,
  ai_reasoning text,
  created_at timestamptz default now() not null,
  updated_at timestamptz default now() not null,
  provider_send_id text,
  last_sent_at timestamptz,
  broker_ids jsonb default '[]'::jsonb not null,
  priority text default 'normal'::text not null,
  partner_logo_url text,
  partner_logo_width integer,
  partner_logo_height integer,
  pinned boolean default false not null,
  cadence_changed_at timestamptz,
  campaign_kind text default 'single'::text not null,
  group_listings jsonb default '[]'::jsonb not null,
  template_version text,
  template_synced_at timestamptz,
  listing_synced_at timestamptz,
  intro_text text,
  priority_rank integer,
  email_subject text,
  preview_text text,
  constraint email_campaigns_pkey PRIMARY KEY (id),
  constraint email_campaigns_campaign_type_check CHECK ((campaign_type = ANY (ARRAY['one-time'::text, 'recurring'::text]))),
  constraint email_campaigns_frequency_check CHECK ((frequency = ANY (ARRAY['one-time'::text, 'weekly'::text, 'bi-weekly'::text, 'monthly'::text]))),
  constraint email_campaigns_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'scheduled'::text, 'active'::text, 'paused'::text, 'completed'::text, 'cancelled'::text])))
);

create index if not exists email_campaigns_group_listings_idx ON public.email_campaigns USING gin (group_listings);
create index if not exists email_campaigns_recurring_due_idx ON public.email_campaigns USING btree (next_send_date) WHERE ((status = 'active'::text) AND (campaign_type = 'recurring'::text));
create index if not exists idx_campaigns_listing ON public.email_campaigns USING btree (listing_id);
create index if not exists idx_campaigns_next_send ON public.email_campaigns USING btree (next_send_date);
create index if not exists idx_campaigns_scheduled ON public.email_campaigns USING btree (scheduled_date);
create index if not exists idx_campaigns_status ON public.email_campaigns USING btree (status);

create table if not exists email_settings (
  id text default 'default'::text not null,
  settings jsonb default '{}'::jsonb not null,
  updated_at timestamptz default now() not null,
  constraint email_settings_pkey PRIMARY KEY (id)
);

create table if not exists email_sends (
  broadcast_id text not null,
  campaign_id uuid,
  scheduled_at timestamptz,
  created_at timestamptz default now() not null,
  constraint email_sends_pkey PRIMARY KEY (broadcast_id)
);

create table if not exists email_events (
  id uuid default gen_random_uuid() not null,
  event_type text not null,
  broadcast_id text,
  campaign_id uuid,
  email_id text,
  occurred_at timestamptz not null,
  payload jsonb,
  created_at timestamptz default now() not null,
  constraint email_events_pkey PRIMARY KEY (id)
);

create index if not exists email_events_campaign_idx ON public.email_events USING btree (campaign_id, event_type);
create index if not exists email_events_occurred_idx ON public.email_events USING btree (occurred_at);

create table if not exists email_alerts (
  id uuid default gen_random_uuid() not null,
  campaign_id uuid,
  type text not null,
  message text not null,
  created_at timestamptz default now() not null,
  dismissed_until timestamptz,
  constraint email_alerts_pkey PRIMARY KEY (id),
  constraint email_alerts_campaign_id_type_key UNIQUE (campaign_id, type)
);


-- ============================================================
-- Email contacts and list hygiene
-- ============================================================

create table if not exists email_contacts (
  email text not null,
  resend_id text,
  first_name text,
  last_name text,
  company text,
  unsubscribed boolean default false not null,
  segment_ids text[] default '{}'::text[] not null,
  synced_at timestamptz default now() not null,
  constraint email_contacts_pkey PRIMARY KEY (email)
);

create index if not exists email_contacts_company_trgm ON public.email_contacts USING gin (COALESCE(company, ''::text) gin_trgm_ops);
create index if not exists email_contacts_email_trgm ON public.email_contacts USING gin (email gin_trgm_ops);
create index if not exists email_contacts_name_trgm ON public.email_contacts USING gin ((((COALESCE(first_name, ''::text) || ' '::text) || COALESCE(last_name, ''::text))) gin_trgm_ops);
create index if not exists email_contacts_segments ON public.email_contacts USING gin (segment_ids);

create table if not exists email_contact_health (
  email_hash text not null,
  soft_streak integer default 0 not null,
  last_soft_bounce_at timestamptz,
  last_delivered_at timestamptz,
  last_bounce_kind text,
  suppressed_at timestamptz,
  suppress_reason text,
  updated_at timestamptz default now() not null,
  constraint email_contact_health_pkey PRIMARY KEY (email_hash)
);

create index if not exists email_contact_health_suppressed_idx ON public.email_contact_health USING btree (suppressed_at) WHERE (suppressed_at IS NOT NULL);


-- ============================================================
-- Market intel
-- ============================================================

create table if not exists market_intel (
  id uuid default gen_random_uuid() not null,
  title text not null,
  slug text not null,
  summary text not null,
  impact text not null,
  category intel_category default 'market'::intel_category not null,
  tags text[] default '{}'::text[],
  source_name text,
  source_date date,
  status intel_status default 'pending'::intel_status not null,
  relevance_score smallint default 50,
  original_headline text,
  original_text text,
  created_at timestamptz default now() not null,
  updated_at timestamptz default now() not null,
  published_at timestamptz,
  source_url text,
  original_summary text,
  original_impact text,
  was_edited boolean default false,
  constraint market_intel_pkey PRIMARY KEY (id),
  constraint market_intel_slug_key UNIQUE (slug)
);

create index if not exists idx_market_intel_live ON public.market_intel USING btree (status, category, published_at DESC) WHERE (status = 'live'::intel_status);
create index if not exists idx_market_intel_pending ON public.market_intel USING btree (status, relevance_score DESC) WHERE (status = 'pending'::intel_status);
create index if not exists idx_market_intel_slug ON public.market_intel USING btree (slug);
drop trigger if exists market_intel_updated on market_intel;
CREATE TRIGGER market_intel_updated BEFORE UPDATE ON public.market_intel FOR EACH ROW EXECUTE FUNCTION update_market_intel_timestamp();


-- ============================================================
-- Brand logo library
-- ============================================================

create table if not exists brand_logos (
  id uuid default gen_random_uuid() not null,
  name text not null,
  slug text not null,
  category text not null,
  aliases text[] default '{}'::text[] not null,
  variants jsonb default '{}'::jsonb not null,
  source_url text,
  width integer,
  height integer,
  created_at timestamptz default now() not null,
  constraint brand_logos_pkey PRIMARY KEY (id),
  constraint brand_logos_slug_key UNIQUE (slug)
);


-- ============================================================
-- Foreign keys
-- Added after every table exists so the order above doesn't matter.
-- ============================================================

do $$ begin
  alter table deal_dates add constraint deal_dates_deal_id_fkey FOREIGN KEY (deal_id) REFERENCES deals(id) ON DELETE CASCADE;
exception when duplicate_object then null; end $$;
do $$ begin
  alter table deal_members add constraint deal_members_broker_id_fkey FOREIGN KEY (broker_id) REFERENCES brokers(id) ON DELETE CASCADE;
exception when duplicate_object then null; end $$;
do $$ begin
  alter table deal_members add constraint deal_members_deal_id_fkey FOREIGN KEY (deal_id) REFERENCES deals(id) ON DELETE CASCADE;
exception when duplicate_object then null; end $$;
do $$ begin
  alter table deals add constraint deals_broker_id_fkey FOREIGN KEY (broker_id) REFERENCES brokers(id);
exception when duplicate_object then null; end $$;
do $$ begin
  alter table email_alerts add constraint email_alerts_campaign_id_fkey FOREIGN KEY (campaign_id) REFERENCES email_campaigns(id) ON DELETE CASCADE;
exception when duplicate_object then null; end $$;
do $$ begin
  alter table email_sends add constraint email_sends_campaign_id_fkey FOREIGN KEY (campaign_id) REFERENCES email_campaigns(id) ON DELETE CASCADE;
exception when duplicate_object then null; end $$;
do $$ begin
  alter table lease_payments add constraint lease_payments_deal_id_fkey FOREIGN KEY (deal_id) REFERENCES deals(id) ON DELETE CASCADE;
exception when duplicate_object then null; end $$;

-- ============================================================
-- Application RPCs
-- ============================================================

create or replace function public.patch_checklist_items(p_listing_id text, p_patch jsonb)
 RETURNS SETOF listing_checklists
 LANGUAGE sql
 SET search_path TO 'public', 'extensions'
AS $function$
  update listing_checklists
  set items = items || p_patch,
      is_new = case
        when not exists (select 1 from jsonb_each_text(items || p_patch) where value <> 'true')
        then false else is_new end,
      updated_at = now()
  where listing_id = p_listing_id
  returning *;
$function$;

create or replace function public.audience_overlaps()
 RETURNS TABLE(segment_ids text[], total bigint, subscribed bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  select
    array(select unnest(c.segment_ids) order by 1)::text[] as segment_ids,
    count(*)::bigint as total,
    count(*) filter (where not c.unsubscribed)::bigint as subscribed
  from email_contacts c
  where array_length(c.segment_ids, 1) > 0
  group by 1
$function$;

commit;
